@dataclass(frozen=True)
class ArchInfo:
    id: str
    name: str
    order: int
    cc: str                 # CUDA compute capability
    branch: str | None      # recommended driver branch in the archive (None: no supported driver)
    open_modules: str       # required | recommended | unsupported
    torch: str              # PyTorch wheel backend for uv (UV_TORCH_BACKEND)
    cuda: str               # newest CUDA major that supports the GPU
    legacy: bool


