# Marketing-name fallback (lspci without IDs, nvidia-smi names, unknown new IDs). Order matters.
NAME_PATTERNS: tuple[tuple[str, str], ...] = (
    (r"RTX\s*PRO\s*\d+.*Blackwell|RTX\s*50\d\d|\bB[123]00\b|\bGB\d{2,3}\b|DGX\s*Spark", "blackwell"),
    (r"RTX\s*40\d\d|RTX\s*\d+\s*Ada|\bL40S?\b|\bL4\b|\bAD10\d", "ada"),
    (r"\bH(100|200|800|20)\b|\bGH\d{3}", "hopper"),
    (r"RTX\s*30\d\d|RTX\s*A\d{3,4}\b|\bA(100|10G?|16|2|30|40|800)\b|\bGA10\d", "ampere"),
    (r"RTX\s*20\d\d|GTX\s*16\d\d|TITAN\s*RTX|Quadro\s*RTX|\bT(4|400|600|1000)\b|\bTU1\d\d", "turing"),
    (r"TITAN\s*V\b|V100|\bGV100", "volta"),
    (r"GTX\s*TITAN\s*X\b|GTX\s*9\d\d|GTX\s*750|Quadro\s*M\d+|\bM(40|60)\b|\bGM\d{3}", "maxwell"),
    (r"GTX\s*10\d\d|GT\s*10\d\d|TITAN\s*Xp?\b|P100|P40|\bP4\b|Quadro\s*P\d+|\bGP10\d", "pascal"),
    (r"GTX\s*[67]\d\d|GT\s*[67]\d\d|\bGK\d{3}|Tesla\s*K\d+", "kepler"),
)


def arch_from_id(device_id: int) -> str | None:
    for lo, hi, arch in ARCH_RANGES:
        if lo <= device_id <= hi:
            return arch
    return None


def arch_from_name(name: str) -> str | None:
    for pat, arch in NAME_PATTERNS:
        if re.search(pat, name or "", re.IGNORECASE):
            return arch
    return None


def arch_for(device_id: int | None, name: str | None = None) -> str | None:
    arch = arch_from_id(device_id) if device_id is not None else None
    return arch or arch_from_name(name or "")


def info(arch: str | None) -> ArchInfo | None:
    return ARCH.get(arch or "")


def driver_packages(branch: str, open_modules: bool, kernel_flavor: str = "generic") -> list[str]:
    """Canonical-signed prebuilt modules (Secure Boot works without MOK enrollment)."""
    sfx = "-open" if open_modules else ""
    return [f"nvidia-driver-{branch}{sfx}", f"linux-modules-nvidia-{branch}{sfx}-{kernel_flavor}"]


def kernel_flavor(release: str) -> str:
    """``6.17.0-9-generic`` → ``generic``; ``6.17.0-1004-lowlatency`` → ``lowlatency``."""
    m = re.match(r"^\d+\.\d+\.\d+-\d+-(.+)$", release or "")
    return m.group(1) if m else "generic"


def parse_version(v: str | None) -> tuple[int, ...]:
    if not v:
        return ()
    return tuple(int(x) for x in re.findall(r"\d+", v)[:3])
